INSERT INTO core_roles (id, company_id, name, description, is_system, created_at, updated_at) VALUES
  ('b724f650-5ed7-56e1-811c-68edc0197f8b', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Organization Owner / CEO', 'Full visibility and control across every module, branch and approval chain.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('c5f14978-d923-57f6-860a-00b1820baa8d', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'C-Level Executive', 'Company-wide visibility with edit rights over org structure, benefits and platform settings.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('1b2be62b-e543-5d1d-bccd-6958286c044a', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'VP / Director', 'Company-wide visibility across your function, with edit rights on performance and org structure.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('82417c62-c3f4-538f-81a2-e235b25d5617', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'General Manager / Sr. Manager', 'Your reporting line only — attendance, leave and timesheet approvals for your team.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('02e88658-ad46-59ff-b578-ce480395ff39', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Manager', 'Your direct reports only — day-to-day approvals, no org-wide administration.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('ccb57b58-4a81-5f3d-aabf-49d83f774d41', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Team Lead', 'Your squad only — first-line attendance & timesheet review, view-only on leave and org data.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('c71f1de3-7595-512f-88b3-89ac2429f5df', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'HR / Recruitment Staff', 'Full People, Recruitment and Benefits administration; no org-structure or platform settings access.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('65f2f8ff-7023-539e-a98e-f2bb2ec14c09', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Finance / Payroll Staff', 'Full payroll processing and benefits administration; no attendance, performance or recruitment access.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('ed3ee118-aa6b-5592-8156-6f7d1fde67c2', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'IT / System Admin', 'Full platform administration and asset management; no HR, payroll or performance access.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('7bded302-3444-54be-a3f6-562304941204', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Branch Manager', 'Branch-scoped view of people, attendance and performance; no payroll, recruitment or platform access.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('7e9da014-8e9f-5fdf-a346-05ce616a28f5', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Branch Head', 'Oversees every Branch Manager company-wide — cross-branch visibility and approvals, no platform administration.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('a7e82e35-a46f-56c2-bf07-8b5031a908c6', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Project Manager', 'Approve leave, timesheets and travel for your project team; view-only on broader org and payroll data.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('ae918285-d171-5955-b733-528002bca3c1', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Professional / IC Employee', 'Self-service only — your profile, attendance, leave, payslip and assigned work.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00'),
  ('01bb2bfd-114f-55f2-9952-889812d56415', '4cd275cb-a7ec-58c5-8e3e-f04a0d9fe41a', 'Associate / Intern', 'Self-service only — your profile, attendance, leave, payslip and assigned work.', TRUE, '2026-09-01T09:00:00', '2026-09-01T09:00:00');
